output_text:
[
  {
    "id": "entry_cart_required",
    "text": "A shopper is obliged to take the cart from the entry cart station before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_entry_cart": "hasCart"
      },
      "events": {
        "took_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "has_entry_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "took_entry_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying merchandise by hand rather than using a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "not_using_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "became_hand_carrying": {
          "pre": {
            "not": "carrying_item_by_hand"
          },
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "A shopper is prohibited from picking up an item unless they currently have the cart.",
    "abstraction": {
      "state_properties": {
        "using_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        },
        "pickup_item_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "using_cart"
            ]
          },
          "post": "using_cart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "After any item has been loaded into the cart, the shopper is obliged eventually to return the cart to the designated return bay.",
    "abstraction": {
      "state_properties": {
        "using_cart": "hasCart",
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "loaded_item_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "using_cart"
            ]
          },
          "post": "using_cart"
        },
        "returned_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "loaded_item_into_cart",
      "discharge": "returned_cart_to_bay"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A shopper is prohibited from leaving the cart anywhere except the designated return bay at the northwest corner.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "outside_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "abandoned_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_cart_return_bay"
            ]
          },
          "post": null
        },
        "properly_parked_cart": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "cart_return_bay"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandoned_cart_outside_bay"
    }
  },
  {
    "id": "release_cart_when_at_return_bay",
    "text": "When a shopper reaches the return bay while still holding the cart, they are obliged to release the cart there.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "at_return_bay_with_cart": {
          "and": [
            "cart_return_bay",
            "hasCart"
          ]
        },
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "returned_cart_to_bay": {
          "pre": {
            "and": [
              "at_return_bay_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "at_return_bay_with_cart",
      "discharge": "returned_cart_to_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from exiting the store while still in possession of the cart.",
    "abstraction": {
      "state_properties": {
        "using_cart": "hasCart",
        "exit_cell": "at(9,5)"
      },
      "events": {
        "exit_while_using_cart": {
          "pre": {
            "and": [
              "EXIT",
              "using_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_while_using_cart"
    }
  },
  {
    "id": "cart_only_on_cart_lanes",
    "text": "While pushing a cart, a shopper is prohibited from taking it off the store's cart-permitted lanes and return corridor.",
    "abstraction": {
      "state_properties": {
        "west_return_spine": {
          "or": [
            "at(0,1)",
            "at(0,2)",
            "at(0,3)",
            "at(0,4)"
          ]
        },
        "left_vertical_lane": {
          "or": [
            "at(1,1)",
            "at(1,2)",
            "at(1,3)",
            "at(1,4)",
            "at(1,5)"
          ]
        },
        "bottom_cart_lane": {
          "or": [
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)"
          ]
        },
        "south_item_cart_lane": {
          "or": [
            "at(2,4)",
            "at(3,4)",
            "at(4,4)",
            "at(5,4)",
            "at(6,4)"
          ]
        },
        "north_item_cart_lane": {
          "or": [
            "at(2,2)",
            "at(3,2)",
            "at(4,2)",
            "at(5,2)",
            "at(6,2)"
          ]
        },
        "cart_permitted_lane": {
          "or": [
            "west_return_spine",
            "left_vertical_lane",
            "bottom_cart_lane",
            "south_item_cart_lane",
            "north_item_cart_lane"
          ]
        },
        "off_cart_lane": {
          "not": "cart_permitted_lane"
        }
      },
      "events": {
        "cart_move_off_lane": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              "off_cart_lane"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "off_cart_lane"
        ]
      }
    }
  }
]
